check_code:
F=[dict(TL='O',TR='dn',C='up',BL='tri',BR='sq'),
   dict(TL='up',TR='sq',C='dn',BL='O',BR='tri'),
   dict(TL='dn',TR='tri',C='sq',BL='up',BR='O'),
   dict(TL='sq',TR='O',C='tri',BL='dn',BR='up')]
cyc=['TL','BL','BR','TR','C']
nxt={cyc[i]:cyc[(i+1)%5] for i in range(5)}
for a,b in zip(F,F[1:]):
    assert all(b[nxt[p]]==a[p] for p in a)
F5={nxt[p]:v for p,v in F[3].items()}
opts={'A':dict(TL='O',TR='up',C='sq',BL='tri',BR='dn'),'B':dict(TL='tri',TR='up',C='O',BL='sq',BR='dn'),
      'C':dict(TL='sq',TR='dn',C='O',BL='tri',BR='up'),'D':dict(TL='sq',TR='up',C='tri',BL='O',BR='dn')}
assert F5==opts['B']
for k in 'ACD': assert F5!=opts[k]

F=[dict(TL='A',TR='B',C='E',BL='D',BR='C'),dict(TL='E',TR='A',C='D',BL='C',BR='B'),
   dict(TL='D',TR='E',C='C',BL='B',BR='A'),dict(TL='C',TR='D',C='B',BL='A',BR='E')]
cyc=['TL','TR','BR','BL','C']
nxt={cyc[i]:cyc[(i+1)%5] for i in range(5)}
for a,b in zip(F,F[1:]):
    assert all(b[nxt[p]]==a[p] for p in a)
F5={nxt[p]:v for p,v in F[3].items()}
opts={'A':(dict(TL='D',TR='B',C='A',BL='C',BR='E'),False),'B':(dict(TL='B',TR='C',C='A',BL='E',BR='D'),False),
      'C':(dict(TL='D',TR='B',C='A',BL='C',BR='E'),True),'D':(dict(TL='E',TR='C',C='B',BL='A',BR='D'),True)}
ok=[k for k,(f,mir) in opts.items() if f==F5 and not mir]
assert ok==['B']
